using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Edits the message content of a checklist. Returns the edited message after the edit is completed on the server side
    /// </summary>
    public Task<TdLib.TdApi.Objects.Message> EditMessageChecklistAsync(long chatId = default, long messageId = default, ReplyMarkup replyMarkup = default, InputChecklist checklist = default)
    {

           using var activity =  StartCallActivity("EditMessageChecklistAsync", typeof(EditMessageChecklist).FullName ?? "EditMessageChecklistAsync");

           try
           {
             return client.EditMessageChecklistAsync(chatId, messageId, replyMarkup, checklist);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
